// 动效时长（毫秒），顺序与 DurationName 一致：instant、quick、base、smooth、slow；
// 标准档是 :root 的 --motion-duration-*，减弱档是 html[data-motion="reduced"] 的覆盖值。
var motionStandardMs = [...]int{80, 120, 180, 280, 420}
var motionReducedMs = [...]int{50, 80, 110, 170, 250}

// HuePresets 是设置里的 6 个主题色预设（MORANDI_THEMES）。
var HuePresets = []HuePreset{
	{ID: "royal-blue", Name: "Royal Blue", Hue: 220, Saturation: 70},
	{ID: "blue", Name: "Misty Blue", Hue: 210, Saturation: 35},
	{ID: "purple", Name: "Smoky Purple", Hue: 260, Saturation: 30},
	{ID: "green", Name: "Bean Green", Hue: 150, Saturation: 30},
	{ID: "orange", Name: "Apricot Orange", Hue: 25, Saturation: 40},
	{ID: "teal", Name: "Teal Blue", Hue: 175, Saturation: 30},
}

// FontSizes 是设置里的字号档（FONT_SIZES）；Px 是该档的根字号。
var FontSizes = []FontSizePreset{
	{ID: "small", Name: "Small", Px: 14},
	{ID: "medium", Name: "Medium", Px: 16},
	{ID: "large", Name: "Large", Px: 18},
}

const (
	// DefaultHuePreset 与 DefaultFontSize 是设置的默认值。
	DefaultHuePreset = "royal-blue"
	DefaultFontSize  = "medium"
	// RadiusRem 是 --radius（rem）；控件圆角在此基础上按 Tailwind 的 md/lg 档取值。
	RadiusRem = 0.75
)
